let parsed = {};
try { parsed = JSON.parse(stripFences(content)); } catch {}
const searchFailed = Boolean(prepared.serper_error) && (!Array.isArray(prepared.serper_results) || prepared.serper_results.length === 0);
const pickedUrl = searchFailed ? '' : normalizeUrl(parsed.url || '');
const canonical = canonicalDomain(pickedUrl);
