const sourceItems = $('Prepare Public Enrichment').all();
function stringify(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number') return String(value);
  if (typeof value === 'object') {
    return String(value.message || value.error || value.code || JSON.stringify(value));
  }
  return String(value);
}
function isTransportTimeout(value) {
  const text = stringify(value).toLowerCase();
  return text.includes('timeout of') || text.includes('etimedout') || text.includes('socket hang up') || text.includes('econnreset');
}
function enrichmentDepth(patch) {
  try {
    const parsed = typeof patch.structured_data_detected === 'string' ? JSON.parse(patch.structured_data_detected) : patch.structured_data_detected;
    return (parsed && parsed.enrichment_depth) || {};
  } catch {
    return {};
  }
}
function terminalStatus(patch) {
  const stage = String(patch.last_stage || patch.crawl_status || '').trim();
  if (stage === 'crawled') return 'completed';
  if (stage === 'partial') return String(patch.best_url || '').trim() ? 'completed' : 'needs_review';
  if (stage === 'crawl_failed' || stage === 'enrichment_error') return 'failed';
  if (stage === 'blocked_by_robots' || stage.startsWith('skipped_')) return 'skipped';
  if (!String(patch.best_url || '').trim()) return 'needs_review';
  return 'completed';
}
function statusReason(status, patch) {
  const stage = String(patch.last_stage || patch.crawl_status || '').trim();
  const depthMeta = enrichmentDepth(patch);
  const depth = String(patch.enrichment_depth_status || depthMeta.enrichment_depth_status || '').trim();
  const weakReason = String(patch.weak_enrichment_reason || depthMeta.weak_enrichment_reason || '').trim();
  if (depth === 'weak_retry_needed') return weakReason || 'weak_retry_needed';
  if (status === 'completed') return stage === 'partial' ? 'enrichment_completed_with_subpage_warnings' : 'enrichment_completed';
  if (status === 'needs_review') return stage === 'partial' ? 'partial_crawl' : 'ambiguous_enrichment';
  if (status === 'skipped') return stage || 'skipped';
  return stage || 'failed';
}
return $input.all().flatMap((item, index) => {
